pub fn top_k(words: List[Str], k: Int) -> List[Str] {
  let distinct = words.unique()
  let keyed = distinct.map(fn(w: Str) -> Str {
    let c = words.count(fn(x: Str) => x == w)
    return (999999 - c).to_str().pad_left(6, "0") + w
  })
  return keyed.sort().take(k).map(fn(s: Str) => s.slice(6, s.len()))
}
